import sys
import traceback


def _test(expected, actual, call):
    try:
        assert actual == expected, "{} should return {}. Your code: {}".format(call, expected, actual)
        print("\u2713 passed: {} \u2192 {}".format(call, expected))
    except AssertionError as ae:
        print("\u2717 failed: {}".format(ae))


class QueueTests:

    def __init__(self, module_name):
        self.module = module_name

    def test_01_constructor(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            queue = self.module.Queue()
            print("\u2713 passed: {} constructor call".format('Queue()'))
        except Exception as e:
            print("\u2717 FAILED. The constructor raised an exception. {}: {}".format(type(e).__name__, e))
            print(traceback.format_exc())

    def test_02_enqueue_dequeue(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            queue = self.module.Queue()
            _test(expected=None,
                  actual=queue.enqueue(5),
                  call="enqueue(5)")

            _test(expected=None,
                  actual=queue.enqueue('Joe'),
                  call="then enqueue('Joe')")

            _test(expected=5,
                  actual=queue.dequeue(),
                  call="Now dequeue()")

            _test(expected=None,
                  actual=queue.enqueue('Horace'),
                  call="then enqueue('Horace')")

            _test(expected=None,
                  actual=queue.enqueue('Esther'),
                  call="then enqueue('Esther')")

            _test(expected='Joe',
                  actual=queue.dequeue(),
                  call="now dequeue() again")

            _test(expected='Horace',
                  actual=queue.dequeue(),
                  call="now dequeue() again")
        except NotImplementedError:
            print("\u2717 FAILED: A method is raising Not Implemented")
            return
        except Exception as e:
            print("\u2717 FAILED. calling enqueue() raised an exception. {}: {}".format(type(e).__name__, e))
            print(traceback.format_exc())

    def test_03_dequeue_empty(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            queue = self.module.Queue()
            _test(expected=None,
                  actual=queue.dequeue(),
                  call="calling dequeue() on an empty queue")
        except NotImplementedError:
            print("\u2717 FAILED: A method is raising Not Implemented")
            return
        except Exception as e:
            print("\u2717 FAILED. calling dequeue() raised an exception. {}: {}".format(type(e).__name__, e))
            print(traceback.format_exc())

    def test_04_is_empty(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            queue = self.module.Queue()
            _test(expected=True,
                  actual=queue.is_empty(),
                  call="is_empty() on an empty queue")

            queue.enqueue(5)
            _test(expected=False,
                  actual=queue.is_empty(),
                  call="called enqueue(5), then is_empty()")

            queue.dequeue()
            _test(expected=True,
                  actual=queue.is_empty(),
                  call="called dequeue(), then is_empty() again")

        except NotImplementedError:
            print("\u2717 FAILED: A method is raising Not Implemented")
            return
        except Exception as e:
            print("\u2717 FAILED. calling is_empty() raised an exception. {}: {}".format(type(e).__name__, e))
            print(traceback.format_exc())

    def test_05__len__(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            queue = self.module.Queue()
            _test(expected=0,
                  actual=len(queue),
                  call="len(queue) on an empty queue")

            queue.enqueue(5)
            queue.enqueue('Joe')
            _test(expected=2,
                  actual=len(queue),
                  call="called enqueue(5) then enqueue('Joe'). now len(queue)")

            queue.dequeue()
            _test(expected=1,
                  actual=len(queue),
                  call="called dequeue(). now len(queue)")

        except NotImplementedError:
            print("\u2717 FAILED: A method is raising Not Implemented")
            return
        except Exception as e:
            print("\u2717 FAILED. calling len(queue) raised an exception. {}: {}".format(type(e).__name__, e))
            print(traceback.format_exc())

    def test_all(self):
        self.test_01_constructor()
        self.test_02_enqueue_dequeue()
        self.test_03_dequeue_empty()
        self.test_04_is_empty()
        self.test_05__len__()
